import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        n = len(S)
        seen = set()

        for i in range(n):
            count_ones = 0
            for j in range(i, n):
                if S[j] == '1':
                    count_ones += 1

                if count_ones % 2 == 0:
                    ones = 0
                    zeros = 0
                    for k in range(i, j + 1):
                        if S[k] == '1':
                            ones += 1
                        else:
                            zeros += 1
                    canonical = ('1' * ones) + ('0' * zeros)
                else:
                    ones = 0
                    zeros = 0
                    first_one_idx = -1
                    last_one_idx = -1
                    for k in range(i, j + 1):
                        ch = S[k]
                        if ch == '1':
                            ones += 1
                            if first_one_idx == -1:
                                first_one_idx = k
                            last_one_idx = k
                        else:
                            zeros += 1

                    if ones > 0:
                        zeros_before = first_one_idx - i
                        zeros_after = j - last_one_idx
                        zeros_middle = zeros - zeros_before - zeros_after

                        canonical = ('0' * zeros_before) + ('1' * ones) + ('0' * zeros_middle) + ('0' * zeros_after)
                    else:
                        canonical = '0' * zeros

                seen.add(canonical)

        results.append(str(len(seen)))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
